$m2_l12_t3_starter$, $m2_l12_t3_solution$import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long ans = 1;
        for (int i = 2; i <= n; i++) ans *= i;
        System.out.println(ans);
    }
}
