  JOIN courses c ON c.id = m.course_id AND c.slug = 'java-zero-core'
  WHERE m.position = 3 AND l.position = 4
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

