        String pattern = br.readLine();
        if (text == null) text = "";
        if (pattern == null || pattern.isEmpty()) {
            System.out.println(0);
            return;
        }
        int idx = 0;
        int cnt = 0;
        while (true) {
            int pos = text.indexOf(pattern, idx);
            if (pos < 0) break;
            cnt++;
            idx = pos + pattern.length();
        }
        System.out.println(cnt);
    }
}
